// MT2009_PLUS_YOHARA_CRACK_V1 (no drop): Zaklety Las (SZC) - the Time Rift dungeons (map 404 and its instances
// 4040000+; server-patches/szczelina). The pl-wiki: "W tej lokacji potwory nie daja dropu ... ale w zamian daja
// wiecej Doswiadczenia" - whatever dies there drops no item (its tables, the world's extras, the awakening stone,
// the talisman, the rank fruits, the quest drops) and no yang but its own: Jotun Thrym (SZC) has gold_min/gold_max
// in mob_proto (the tr-wiki's 10-27 million), the other monsters none. The experience, the quests' kills, the cards'
// missions and the Battle Pass stay.
static bool Mt2009PlusTimeRiftNoDrop(LPCHARACTER victim)
{
	if (!victim || victim->IsPC())
		return false;
	const long mapIndex = victim->GetMapIndex();
	const long base = mapIndex >= 10000 ? mapIndex / 10000 : mapIndex;
	return base == 404;
}

void CHARACTER::Reward(bool bItemDrop)

// MT2009_PLUS_YOHARA_CRACK_V1 (rank fruits): none from the Time Rift dungeons (Mt2009PlusTimeRiftNoDrop).
if (!Mt2009PlusTimeRiftNoDrop(this))
{ void RankPointsOnKill(LPCHARACTER, LPCHARACTER); RankPointsOnKill(pkQuestKiller, this); }

	sys_log(0, "Drop money : Attacker %s", pkAttacker->GetName());
RewardGold(pkAttacker);

// MT2009_PLUS_YOHARA_CRACK_V1 (items): nothing more in the Time Rift dungeons - the yang above is the
// mob_proto's own (Jotun Thrym (SZC) only).
if (Mt2009PlusTimeRiftNoDrop(this))
	return;
